import React, { useState } from "react";
import { useHistory, Link } from "react-router-dom";
import { registerUser } from "../../api/authApi";

function Register() {
  const history = useHistory();
  const [form, setForm]       = useState({ name: "", email: "", password: "", roles: "USER", phone: "" });
  const [message, setMessage] = useState("");
  const [msgType, setMsgType] = useState("danger");
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);

  const handleChange = (e) => setForm({ ...form, [e.target.name]: e.target.value });

  const register = async () => {
    if (!form.name || !form.email || !form.password || !form.phone) {
      setMsgType("danger");
      setMessage("Please fill in all required fields.");
      return;
    }
    setLoading(true);
    try {
      await registerUser(form);
      setMsgType("success");
      setMessage("Account created! Redirecting…");
      setSuccess(true);
      setTimeout(() => history.push("/login"), 1500);
    } catch {
      setMsgType("danger");
      setMessage("Registration failed. Username or email may already exist.");
    }
    setLoading(false);
  };

  return (
    <div className="d-flex align-items-center justify-content-center min-vh-100 bg-info bg-opacity-10 py-4">
      <div className="card shadow-sm border-0" style={{ maxWidth: "440px", width: "100%" }}>
        <div className="card-body p-4 p-md-5">

          {success ? (
            <div className="text-center py-4">
              <div className="d-inline-flex align-items-center justify-content-center bg-success bg-opacity-10 border border-success rounded-circle mb-3"
                   style={{ width: "72px", height: "72px", fontSize: "34px" }}>
                ✅
              </div>
              <h5 className="fw-bold mb-1">Account Created!</h5>
              <p className="text-muted small mb-0">Redirecting you to sign in…</p>
            </div>
          ) : (
            <>
              <div className="text-center mb-4">
                <div className="d-inline-flex align-items-center justify-content-center bg-primary rounded-circle mb-2"
                     style={{ width: "56px", height: "56px", fontSize: "26px" }}>
                  🏦
                </div>
                <h4 className="fw-bold mb-1">Create your account</h4>
                <p className="text-muted small mb-0">Get started with FinGenie Bank</p>
              </div>

              {message && (
                <div className={`alert alert-${msgType} py-2 small`} role="alert">
                  {message}
                </div>
              )}

              <div className="row">
                <div className="col-6 mb-3">
                  <label className="form-label small fw-semibold">Full Name</label>
                  <input name="name" type="text" className="form-control" placeholder="John Doe" onChange={handleChange} />
                </div>
                <div className="col-6 mb-3">
                  <label className="form-label small fw-semibold">Phone</label>
                  <input name="phone" type="tel" className="form-control" placeholder="+91 98765 43210" onChange={handleChange} />
                </div>
              </div>

              <div className="mb-3">
                <label className="form-label small fw-semibold">Email Address</label>
                <input name="email" type="email" className="form-control" placeholder="you@example.com" onChange={handleChange} />
              </div>

              <div className="mb-3">
                <label className="form-label small fw-semibold">Password</label>
                <input name="password" type="password" className="form-control" placeholder="Create a strong password" onChange={handleChange} />
              </div>

              <div className="mb-4">
                <label className="form-label small fw-semibold">Account Role</label>
                <select name="roles" className="form-select" onChange={handleChange}>
                  <option value="USER">User</option>
                  <option value="ADMIN">Admin</option>
                </select>
              </div>

              <button
                className="btn btn-primary w-100 d-flex align-items-center justify-content-center gap-2"
                onClick={register}
                disabled={loading}
              >
                {loading ? (
                  <>
                    <span className="spinner-border spinner-border-sm" role="status"></span>
                    Creating account…
                  </>
                ) : (
                  "Create Account"
                )}
              </button>

              <p className="text-center small text-muted mt-4 mb-0">
                Already have an account? <Link to="/login">Sign in</Link>
              </p>
            </>
          )}

        </div>
      </div>
    </div>
  );
}

export default Register;
